import json
n=28
g=[[0]*n for _ in range(n)]
# Preserve the regular 5x5 lattice separators; last 3 rows/cols are partial margins.
for k in [4,9,14,19,24]:
    for x in range(n): g[k][x]=8; g[x][k]=8
# Each full 4x4 cell gets color determined by marked full-cell row/column.
for br in range(5):
  for bc in range(5):
    colors=set()
    if br==1 or bc==0: colors.add(2)
    if bc==2: colors.add(3)
    color=6 if colors=={2,3} else (next(iter(colors)) if colors else 0)
    for r in range(br*5, br*5+4):
      for c in range(bc*5, bc*5+4): g[r][c]=color
print(json.dumps(g,separators=(',',':')))

